using System;using System.IO;using System.Collections;using System.Linq;using UnityEngine;using UnityEngine.SceneManagement;using UnityEngine.Rendering;using UnityEngine.Rendering.Universal;using LWS.TruckSports;
namespace LWS.TruckBaseJumping {public sealed class BaseViewSmoke:MonoBehaviour {
#if UNITY_EDITOR || DEVELOPMENT_BUILD
 [RuntimeInitializeOnLoadMethod]static void Boot(){if(Array.IndexOf(Environment.GetCommandLineArgs(),"-tsBaseView")<0)return;var go=new GameObject("Base visual isolation probe");DontDestroyOnLoad(go);go.AddComponent<BaseViewSmoke>();}
 IEnumerator Start(){string folder=LWS.TruckSports.SportsEvidencePaths.Folder("BaseViewEvidence");Directory.CreateDirectory(folder);yield return new WaitForSeconds(.4f);SceneManager.LoadScene("TruckBaseJumping");yield return new WaitForSeconds(.6f);var m=FindAnyObjectByType<BaseJumpMatch>();m.AllBots();m.StartMatch();yield return new WaitForSeconds(7);var t=m.jumpers[0].truck;var c=m.cameras[0];Debug.Log("BASE_CAMERA_PROBE camera="+c.transform.position+" forward="+c.transform.forward+" body="+t.body.position+" view="+c.WorldToViewportPoint(t.body.position));foreach(var r in t.visuals.GetComponentsInChildren<Renderer>())Debug.Log("BASE_MESH_PROBE "+r.name+" bounds="+r.bounds+" shader="+r.sharedMaterial.shader.name);ScreenCapture.CaptureScreenshot(Path.Combine(folder,"01-original.png"));yield return new WaitForSeconds(.3f);foreach(var v in FindObjectsByType<Volume>(FindObjectsInactive.Include))if(v.sharedProfile!=null&&v.sharedProfile.TryGet<Bloom>(out var bloom)){bloom.active=true;bloom.intensity.Override(.14f);bloom.clamp.Override(2);}ScreenCapture.CaptureScreenshot(Path.Combine(folder,"02-no-bloom.png"));yield return new WaitForSeconds(.3f);foreach(var r in m.weatherField.vendor.GetComponentsInChildren<Renderer>(true))if(r.name.Contains("SkySphere")||r.name.Contains("SkyPlane")){Debug.Log("BASE_SKY_DISABLED "+r.name);r.enabled=false;}ScreenCapture.CaptureScreenshot(Path.Combine(folder,"03-no-vendor-sky.png"));yield return new WaitForSeconds(.3f);foreach(var j in m.jumpers)foreach(var r in j.truck.visuals.GetComponentsInChildren<Renderer>())if(r.name.ToLowerInvariant().Contains("light")||r.name.ToLowerInvariant().Contains("flare"))r.enabled=false;ScreenCapture.CaptureScreenshot(Path.Combine(folder,"04-no-light-meshes.png"));yield return new WaitForSeconds(.4f);Application.Quit();}
#endif
}}
